/******************************************************************************/
/***                                 Tables                                 ***/
/******************************************************************************/



CREATE TABLE CATEGORIA (
    ID      D_ID NOT NULL,
    NOME    D_NOME NOT NULL,
    ID_PAI  INTEGER
);

CREATE TABLE CLIENTE (
    ID         D_ID NOT NULL,
    CODIGO     D_CODIGO,
    NOME       D_NOME NOT NULL,
    CIDADE     VARCHAR(60),
    UF         CHAR(2) DEFAULT 'SP',
    LIMITE     D_DINHEIRO,
    SITUACAO   D_SITUACAO,
    DESCONTO   D_PERCENTUAL,
    OBS        D_OBS,
    CRIADO_EM  D_DATAHORA
);

CREATE TABLE ITEM_PEDIDO (
    ID          D_ID NOT NULL,
    ID_PEDIDO   INTEGER NOT NULL,
    ID_PRODUTO  INTEGER NOT NULL,
    QUANTIDADE  INTEGER DEFAULT 1 NOT NULL,
    PRECO_UNIT  D_DINHEIRO,
    SUBTOTAL    COMPUTED BY (QUANTIDADE * PRECO_UNIT)
);

CREATE TABLE "LOG" (
    ID        D_ID NOT NULL,
    QUANDO    D_DATAHORA,
    TABELA    VARCHAR(31) NOT NULL,
    OPERACAO  CHAR(1) NOT NULL,
    DETALHE   VARCHAR(255)
);

CREATE TABLE PEDIDO (
    ID           D_ID NOT NULL,
    ID_CLIENTE   INTEGER NOT NULL,
    DATA_PEDIDO  D_DATA NOT NULL,
    STATUS       VARCHAR(10) DEFAULT 'ABERTO' NOT NULL,
    TOTAL        D_DINHEIRO,
    OBS          BLOB SUB_TYPE 1 SEGMENT SIZE 80
);

CREATE TABLE PRODUTO (
    ID            D_ID NOT NULL,
    ID_CATEGORIA  INTEGER,
    DESCRICAO     D_NOME NOT NULL,
    PRECO         D_DINHEIRO,
    CUSTO         NUMERIC(15,4) DEFAULT 0,
    MARGEM        COMPUTED BY (CASE WHEN CUSTO > 0 THEN (PRECO - CUSTO) / CUSTO * 100 ELSE NULL END),
    ESTOQUE       INTEGER DEFAULT 0 NOT NULL,
    ATIVO         D_FLAG,
    FOTO          D_BINARIO,
    PESO          D_DOUBLE
);

CREATE TABLE TIPOS_VARIOS (
    ID          INTEGER NOT NULL,
    C_SMALLINT  SMALLINT,
    C_BIGINT    D_BIGINT,
    C_NUM       NUMERIC(18,4),
    C_DEC       DECIMAL(9,2),
    C_FLOAT     FLOAT,
    C_CHAR      CHAR(5),
    C_VARCHAR   VARCHAR(100) CHARACTER SET WIN1252,
    C_TIME      TIME,
    C_DATE      DATE,
    C_TS        TIMESTAMP,
    C_BLOB      BLOB SUB_TYPE 1 SEGMENT SIZE 100,
    C_VETOR     INTEGER [1:5]
);



